import 'dart:async';
import 'dart:math';

import 'package:audioplayers/audioplayers.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

/// Short sound effects (generated by `tool/generate_sounds.dart`).
///
/// Fill and cross sounds climb a pentatonic ladder: pass a growing `step`
/// while the player keeps dragging and the pitch gets higher and thinner.
/// Every call is fire-and-forget and never throws, so a missing audio
/// backend (tests, unsupported platform) just means silence.
class SoundService {
  SoundService({this.voices = 8});

  /// Number of notes that may overlap.
  final int voices;

  static const ladderSize = 15;

  bool enabled = true;

  final _players = <AudioPlayer>[];
  var _next = 0;
  var _warmedUp = false;

  /// Loads every sound so the first play has no delay.
  Future<void> warmUp() async {
    if (_warmedUp) return;
    _warmedUp = true;
    try {
      await AudioCache.instance.loadAll([
        for (var i = 0; i < ladderSize; i++) ...[
          _path('fill', i),
          _path('cross', i),
        ],
        'audio/mistake.wav',
        'audio/line.wav',
        'audio/win.wav',
        'audio/hint.wav',
        'audio/combo.wav',
      ]);
    } on Object {
      // Silent fallback.
    }
  }

  String _path(String name, int step) =>
      'audio/${name}_${step.clamp(0, ladderSize - 1).toString().padLeft(2, '0')}'
      '.wav';

  void fill(int step) => _play(_path('fill', step), 0.8);
  void cross(int step) => _play(_path('cross', step), 0.55);
  void mistake() => _play('audio/mistake.wav', 0.9);
  void line() => _play('audio/line.wav', 0.9);
  void win() => _play('audio/win.wav', 1);
  void combo() => _play('audio/combo.wav', 0.9);
  void hint() => _play('audio/hint.wav', 0.8);

  void _play(String asset, double volume) {
    if (!enabled) return;
    unawaited(_playAsync(asset, volume));
  }

  Future<void> _playAsync(String asset, double volume) async {
    try {
      if (_players.length < voices) {
        final created = AudioPlayer();
        await created.setReleaseMode(ReleaseMode.stop);
        await created.setPlayerMode(PlayerMode.lowLatency);
        _players.add(created);
      }
      final player = _players[_next % _players.length];
      _next = (_next + 1) % max(voices, 1);
      await player.play(AssetSource(asset), volume: volume);
    } on Object {
      // Silent fallback.
    }
  }

  void dispose() {
    for (final p in _players) {
      unawaited(p.dispose());
    }
    _players.clear();
  }
}

final soundServiceProvider = Provider<SoundService>((ref) {
  final service = SoundService();
  unawaited(service.warmUp());
  ref.onDispose(service.dispose);
  return service;
});
